// ========================================
// BC/NAV-style Filtering and Search
// ========================================

// userFilterCondition represents a filter on a field
type userFilterCondition struct {
	fieldName    string
	minValue     interface{}
	maxValue     interface{}
	filterExpr   string // For complex SetFilter expressions
	isExpression bool   // True if using filterExpr instead of min/max
	invalidField bool   // Filter on an unknown field: matches no rows (fail closed)
}

// SetRange sets a range filter on a field (BC/NAV style)
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
func (t *User) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*userFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of User\n", fieldName)
		t.filters[fieldName] = &userFilterCondition{invalidField: true}
		return
	}

	t.filters[column] = &userFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
	}
}

// SetFilter sets a complex filter expression on a field (BC/NAV style)
// Supports BC/NAV filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), & (AND), * (wildcard), <> (not equal)
// Example: customer.SetFilter("No", "001..003|005")
func (t *User) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*userFilterCondition)
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of User\n", fieldName)
		t.filters[fieldName] = &userFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &userFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

// SetCurrentKey sets the sort order for queries (BC/NAV style)
// Unknown fields are ignored (the primary key order is used if none remain).
// Example: customer.SetCurrentKey("City", "Name")
func (t *User) SetCurrentKey(fields ...string) {
	t.orderByFields = nil
	for _, field := range fields {
		column, ok := t.columnName(field)
		if !ok {
			fmt.Printf("Error: SetCurrentKey on unknown field %q of User\n", field)
			continue
		}
		t.orderByFields = append(t.orderByFields, column)
	}
}

// SetAscending sets the sort direction of the current key (BC/NAV Ascending).
// The default is ascending.
func (t *User) SetAscending(ascending bool) {
	t.descending = !ascending
}

// SetSearch limits the records to those where any of the given fields contains text,
// case-insensitive (the list page search box). Unknown fields are ignored; an empty
// text clears the search.
func (t *User) SetSearch(fields []string, text string) {
	t.searchColumns = nil
	t.searchText = strings.ToLower(strings.TrimSpace(text))
	if t.searchText == "" {
		return
	}
	for _, field := range fields {
		if column, ok := t.columnName(field); ok {
			t.searchColumns = append(t.searchColumns, column)
		}
	}
}

// HasColumn reports whether fieldName (case-insensitive) is a stored column of this
// table. Only such names may be used in filters and sort keys.
func (t *User) HasColumn(fieldName string) bool {
	_, ok := t.columnName(fieldName)
	return ok
}

// columnName maps a field name (case-insensitive) to its database column. Field names
// end up in SQL text (WHERE / ORDER BY / SET), so only names from this allowlist are used.
func (t *User) columnName(fieldName string) (string, bool) {
	switch strings.ToLower(fieldName) {
	case strings.ToLower("user_id"):
		return "user_id", true
	case strings.ToLower("user_name"):
		return "user_name", true
	case strings.ToLower("email"):
		return "email", true
	case strings.ToLower("password_hash"):
		return "password_hash", true
	case strings.ToLower("language"):
		return "language", true
	case strings.ToLower("menu"):
		return "menu", true
	case strings.ToLower("active"):
		return "active", true
	case strings.ToLower("created_at"):
		return "created_at", true
	case strings.ToLower("last_login"):
		return "last_login", true
	}
	return "", false
}

// Reset clears all filters (BC/NAV style)
func (t *User) Reset() {
	t.filters = nil
	t.oldValues = nil
	t.orderByFields = nil
	t.descending = false
	t.searchColumns = nil
	t.searchText = ""
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
}

// buildWhereClause builds WHERE clause from current filters and search
func (t *User) buildWhereClause() (string, []interface{}) {
	if len(t.filters) == 0 && t.searchText == "" {
		return "1=1", nil
	}

	var conditions []string
	var args []interface{}

	if t.searchText != "" {
		if len(t.searchColumns) == 0 {
			conditions = append(conditions, "1=0") // searching, but in no valid column
		} else {
			// LIKE wildcards in the text are matched literally
			pattern := "%" + strings.NewReplacer("\\", "\\\\", "%", "\\%", "_", "\\_").Replace(t.searchText) + "%"
			var ors []string
			for _, column := range t.searchColumns {
				ors = append(ors, "LOWER(CAST("+column+" AS TEXT)) LIKE ? ESCAPE '\\'")
				args = append(args, pattern)
			}
			conditions = append(conditions, "("+strings.Join(ors, " OR ")+")")
		}
	}

	for _, filter := range t.filters {
		if filter.invalidField {
			conditions = append(conditions, "1=0")
		} else if filter.isExpression {
			// Parse BC/NAV filter expression
			clause, exprArgs := t.parseFilterExpression(filter.fieldName, filter.filterExpr)
			conditions = append(conditions, clause)
			args = append(args, exprArgs...)
		} else {
			// Simple range filter
			if filter.minValue != nil && filter.maxValue != nil {
				conditions = append(conditions, fmt.Sprintf("%s BETWEEN ? AND ?", filter.fieldName))
				args = append(args, filter.minValue, filter.maxValue)
			} else if filter.minValue != nil {
				conditions = append(conditions, fmt.Sprintf("%s >= ?", filter.fieldName))
				args = append(args, filter.minValue)
			} else if filter.maxValue != nil {
				conditions = append(conditions, fmt.Sprintf("%s <= ?", filter.fieldName))
				args = append(args, filter.maxValue)
			}
		}
	}

	where := strings.Join(conditions, " AND ")
	if where == "" {
		where = "1=1"
	}

	return where, args
}

// parseFilterExpression parses BC/NAV filter expressions into SQL
// Supports: "100..200" (range), "100|200|300" (OR), "100..200|500" (combined)
func (t *User) parseFilterExpression(fieldName, expr string) (string, []interface{}) {
	var conditions []string
	var args []interface{}

	// Split by | (OR operator)
	orParts := strings.Split(expr, "|")

	for _, part := range orParts {
		part = strings.TrimSpace(part)

		// Check for range (..)
		if strings.Contains(part, "..") {
			rangeParts := strings.Split(part, "..")
			if len(rangeParts) == 2 {
				min := strings.TrimSpace(rangeParts[0])
				max := strings.TrimSpace(rangeParts[1])
				conditions = append(conditions, fmt.Sprintf("%s BETWEEN ? AND ?", fieldName))
				args = append(args, min, max)
			}
		} else if strings.Contains(part, "*") {
			// Wildcard support: convert * to %
			likePattern := strings.ReplaceAll(part, "*", "%")
			conditions = append(conditions, fmt.Sprintf("%s LIKE ?", fieldName))
			args = append(args, likePattern)
		} else if strings.HasPrefix(part, "<>") {
			// Not equal
			value := strings.TrimSpace(strings.TrimPrefix(part, "<>"))
			conditions = append(conditions, fmt.Sprintf("%s <> ?", fieldName))
			args = append(args, value)
		} else {
			// Exact match
			conditions = append(conditions, fmt.Sprintf("%s = ?", fieldName))
			args = append(args, part)
		}
	}

	// Join with OR
	whereClause := "(" + strings.Join(conditions, " OR ") + ")"
	return whereClause, args
}

// getOrderByClause builds ORDER BY clause from current key and direction, with the
// arguments of its placeholders (a FlowField key sorts on its subquery, which may have
// some; they follow the WHERE arguments). The primary key columns always follow the
// current key, so the order is unique and paging (SetPage) never repeats or skips rows
// when the key has duplicate values.
func (t *User) getOrderByClause() (string, []interface{}) {
	pk := []string{"user_id"}
	var columns []string
	var args []interface{}
	for _, column := range t.orderByFields {
		columns = append(columns, column)
	}
	for _, column := range pk {
		if !slices.Contains(columns, column) {
			columns = append(columns, column)
		}
	}
	if t.descending {
		for i := range columns {
			columns[i] += " DESC"
		}
	}
	return strings.Join(columns, ", "), args
}

// SetPage sets a pagination window for FindSet/FindSetBuffered: return at most
// limit rows, skipping the first offset rows. A limit of 0 disables pagination
// (all matching rows are returned). Negative values are treated as 0.
func (t *User) SetPage(limit, offset int) {
	if limit < 0 {
		limit = 0
	}
	if offset < 0 {
		offset = 0
	}
	t.limit = limit
	t.offset = offset
}

// getLimitClause builds the LIMIT/OFFSET clause from the pagination window.
// Returns an empty string when no limit is set. LIMIT/OFFSET take integer
// literals (not placeholders), which both SQLite and PostgreSQL accept.
func (t *User) getLimitClause() string {
	if t.limit <= 0 {
		return ""
	}
	if t.offset > 0 {
		return fmt.Sprintf(" LIMIT %d OFFSET %d", t.limit, t.offset)
	}
	return fmt.Sprintf(" LIMIT %d", t.limit)
}

// FindFirst finds the first record matching current filters (BC/NAV style)
// Returns true if found, false if not found
func (t *User) FindFirst() bool {
	tableName := UserTableName
	where, args := t.buildWhereClause()

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT user_id, user_name, email, password_hash, language, menu, active, created_at, last_login FROM "%s" WHERE %s ORDER BY user_id ASC LIMIT 1`, tableName, where)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	var user_idNull sql.NullString
	var user_nameNull sql.NullString
	var emailNull sql.NullString
	var password_hashNull sql.NullString
	var languageNull sql.NullString
	var menuNull sql.NullString
	var activeBool sql.NullBool
	var created_atNull sql.NullString
	var last_loginNull sql.NullString

	err := t.db.QueryRow(query, args...).Scan(
		&user_idNull,
		&user_nameNull,
		&emailNull,
		&password_hashNull,
		&languageNull,
		&menuNull,
		&activeBool,
		&created_atNull,
		&last_loginNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return false
		}
		fmt.Printf("Error: Failed to find first User: %v\n", err)
		return false
	}

	// Populate fields
	t.User_id = types.NewCode(user_idNull.String)
	t.User_name = types.NewText(user_nameNull.String)
	t.Email = types.NewText(emailNull.String)
	t.Password_hash = types.NewText(password_hashNull.String)
	t.Language = types.NewCode(languageNull.String)
	t.Menu = types.NewCode(menuNull.String)
	t.Active = activeBool.Bool
	t.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)
	t.Last_login, _ = types.NewDateTimeFromString(last_loginNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

