// FindSet opens a result set matching current filters (BC/NAV style)
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *User) FindSet() bool {
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	tableName := UserTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT user_id, user_name, email, password_hash, language, menu, active, created_at, last_login FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for User: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record in the result set (BC/NAV style)
// Must be called after FindSet() or FindSetBuffered()
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (only with FindSetBuffered)
//   - Next(-3): Skip backward 3 records (only with FindSetBuffered)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *User) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var user_idNull sql.NullString
		var user_nameNull sql.NullString
		var emailNull sql.NullString
		var password_hashNull sql.NullString
		var languageNull sql.NullString
		var menuNull sql.NullString
		var activeBool sql.NullBool
		var created_atNull sql.NullString
		var last_loginNull sql.NullString

		err := t.currentRows.Scan(
			&user_idNull,
			&user_nameNull,
			&emailNull,
			&password_hashNull,
			&languageNull,
			&menuNull,
			&activeBool,
			&created_atNull,
			&last_loginNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan User record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.User_id = types.NewCode(user_idNull.String)
		t.User_name = types.NewText(user_nameNull.String)
		t.Email = types.NewText(emailNull.String)
		t.Password_hash = types.NewText(password_hashNull.String)
		t.Language = types.NewCode(languageNull.String)
		t.Menu = types.NewCode(menuNull.String)
		t.Active = activeBool.Bool
		t.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)
		t.Last_login, _ = types.NewDateTimeFromString(last_loginNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No active recordset
	return false
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation (BC/NAV style)
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *User) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := UserTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT user_id, user_name, email, password_hash, language, menu, active, created_at, last_login FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for User: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &User{}
		record.db = t.db
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var user_idNull sql.NullString
		var user_nameNull sql.NullString
		var emailNull sql.NullString
		var password_hashNull sql.NullString
		var languageNull sql.NullString
		var menuNull sql.NullString
		var activeBool sql.NullBool
		var created_atNull sql.NullString
		var last_loginNull sql.NullString

		err := rows.Scan(
			&user_idNull,
			&user_nameNull,
			&emailNull,
			&password_hashNull,
			&languageNull,
			&menuNull,
			&activeBool,
			&created_atNull,
			&last_loginNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan User record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.User_id = types.NewCode(user_idNull.String)
		record.User_name = types.NewText(user_nameNull.String)
		record.Email = types.NewText(emailNull.String)
		record.Password_hash = types.NewText(password_hashNull.String)
		record.Language = types.NewCode(languageNull.String)
		record.Menu = types.NewCode(menuNull.String)
		record.Active = activeBool.Bool
		record.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)
		record.Last_login, _ = types.NewDateTimeFromString(last_loginNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate User records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *User) copyFromBuffered(record *User) {
	t.User_id = record.User_id
	t.User_name = record.User_name
	t.Email = record.Email
	t.Password_hash = record.Password_hash
	t.Language = record.Language
	t.Menu = record.Menu
	t.Active = record.Active
	t.Created_at = record.Created_at
	t.Last_login = record.Last_login
	t.StoreOldValues()
}

